provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "main" {
  vpc_id          = aws_vpc.main_vpc.id
  cidr_block       = "10.0.1.0/24"
  availability_zone = "us-east-1a"
}

resource "aws_security_group" "main_sg" {
  name        = "main_sg"
  description = "Main security group for the VPC"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "proxy_role" {
  name = "proxy_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_route53_zone" "private" {
  name = "private.example.com"
}

resource "aws_route53_zone" "public" {
  name = "public.example.com"
}

resource "aws_db_instance" "internal" {
  instance_class = "t3.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "5.7"
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.main_sg.id]
  tags = {
    Name = "internal-db"
  }
}

resource "aws_db_instance" "public" {
  instance_class = "t3.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "5.7"
  db_subnet_group_name = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.main_sg.id]
  publicly_accessible = true
  tags = {
    Name = "public-db"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-sg"
  subnet_ids = [aws_subnet.main.id]
}

resource "aws_db_proxy" "internal_proxy" {
  engine_family = "MYSQL"
  name         = "internal-proxy"
  role_arn     = aws_iam_role.proxy_role.arn
  vpc_subnet_ids = [aws_subnet.main.id]

  auth {
    auth_scheme = "password"
    username   = "admin"
    password   = "securepassword123"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_db_proxy" "public_proxy" {
  engine_family = "MYSQL"
  name         = "public-proxy"
  role_arn     = aws_iam_role.proxy_role.arn
  vpc_subnet_ids = [aws_subnet.main.id]

  auth {
    auth_scheme = "password"
    username   = "admin"
    password   = "securepassword123"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}
