provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
}

resource "aws_db_instance" "my_db1" {
  instance_class = "db.t2.micro"
  allocated_storage = 20
  engine = "mysql"
  engine_version = "5.7"
  username = "admin"
  password = "password123"
  db_subnet_group_name = aws_db_subnet_group.my_db_subnet_group.name
  vpc_security_group_ids = [aws_security_group.my_db_sg.id]
  tags = {
    Name = "my_db1"
  }
}

resource "aws_security_group" "my_db_sg" {
  name        = "my_db_sg"
  description = "Security group for the database"
  vpc_id      = aws_vpc.my_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "my_db_subnet_group" {
  name       = "my_db_subnet_group"
  subnet_ids = [aws_subnet.my_subnet.id]

  tags = {
    Name = "my_db_subnet_group"
  }
}

resource "aws_subnet" "my_subnet" {
  cidr_block = "10.0.1.0/24"
  vpc_id      = aws_vpc.my_vpc.id
}

resource "aws_vpc" "my_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_autoscaling_group" "web_app_asg" {
  name                 = "web_app_asg"
  max_size             = 3
  min_size             = 1
  availability_zones = ["us-east-1a", "us-east-1b"]

  launch_configuration = aws_launch_configuration.web_app_lc.name

  health_check_type = "EC2"
  health_check_grace_period = 300

  tag {
    key   = "Name"
    value = "web_app_asg"
    propagate_at_launch = true
  }

  tag {
    key   = "Environment"
    value = "production"
    propagate_at_launch = true
  }
}

resource "aws_launch_configuration" "web_app_lc" {
  image_id           = "ami-0c55b159cbfafe1f0"
  instance_type     = "t3.micro"
  key_name          = "my_key_pair"
  security_groups    = [aws_security_group.web_app_sg.id]
  user_data         = <<-EOF
    #!/bin/bash
    sudo apt-get update
    sudo apt-get install -y nginx
    EOF

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "web_app_sg" {
  name        = "web_app_sg"
  description = "Security group for the web app"
  vpc_id      = aws_vpc.my_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elastic_beanstalk_application" "web_app" {
  name = "web_app"
}

resource "aws_elastic_beanstalk_environment" "web_app_env" {
  application = aws_elastic_beanstalk_application.web_app.name
  name        = "web_app_env"

  instance_profile = aws_iam_instance_profile.eb_ec2_profile.name
  vpc_id          = aws_vpc.my_vpc.id
  solution_stack_name = "64bit Amazon Linux 2 v3.0.0 running Python 3.8"

  database_name = aws_db_instance.my_db1.db_name
  database_username = aws_db_instance.my_db1.username
  database_password = aws_db_instance.my_db1.password

  tags = {
    Name = "web_app_env"
  }
}
