  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lex_bot" "pizza_order_bot" {
  name = "PizzaOrderBot"
  child_directed = false
  description = "A bot to handle pizza orders."

  intents {
    intent_name = "OrderPizzaIntent"
    intent_version = "1"
  }

  utterances = [
    "I want a pizza",
    "Can I order a pizza?",
    "Order a pizza please",
  ]

  abort_statement {
    response_card = jsonencode({
      version = "1.0"
      contentType = "application/vnd.amazonaws.card.generic"
      title = "Sorry, I can't help with that."
      buttons = [
        {
          text = "Cancel"
          value = "Cancel"
        }
      ]
    })
  }

  clarification_prompt {
    max_attempts = 2
    response_card = jsonencode({
      version = "1.0"
      contentType = "application/vnd.amazonaws.card.generic"
      title = "Please rephrase your request."
      buttons = [
        {
          text = "Retry"
          value = "Retry"
        }
      ]
    })
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}
