provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "flink_app_role" {
  name = "flink_app_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_kinesisanalyticsv2_application" "flink_app" {
  name = "flink_app"

  runtime_environment = "FLINK-1_14"
  service_execution_role = aws_iam_role.flink_app_role.id

  application_configuration {
    flink_application_configuration {
      parallelism_configuration {
        parallelism = 1
        auto_scaling_configuration {
          maximum_parallelism = 10
          minimum_parallelism = 1
          target_capacity_unit = 10
        }
      }

      checkpoint_configuration {
        enable_checkpointing = true
        checkpoint_interval = 60000
        checkpoint_timeout = 60000
      }

      monitoring_configuration {
        logging_level = "INFO"
        metrics_level = "ALL"
      }

      application_code_configuration {
        code_content {
          text_content = <<-EOF
            // Example Flink code
            import org.apache.flink.api.common.functions.MapFunction;
            import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;

            public class FlinkApp extends StreamExecutionEnvironment {
              public static void main(String[] args) throws Exception {
                StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

                env.fromElements("Hello", "World")
                  .map(new MapFunction<String, String>() {
                    @Override
                    public String map(String value) throws Exception {
                      return value.toUpperCase();
                    }
                  })
                  .print();

                env.execute("Flink App");
              }
            }
          EOF
        }
        code_content_type = "PLAINTEXT"
      }
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = "arn:aws:logs:us-east-1:123456789012:log-group:/aws/kinesisanalytics/flink_app:log-stream:flink_app"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}
```

