      aws_subnet.private_subnet_az1.id,
      aws_subnet.public_subnet_az1.id,
      aws_subnet.private_subnet_az2.id,
      aws_subnet.public_subnet_az2.id,
      aws_subnet.private_subnet_az3.id,
      aws_subnet.public_subnet_az3.id,
    ]

    endpoint_private_access = true
    endpoint_public_access = true
    public_access_cidrs   = ["0.0.0.0/0"]
  }

  tags = {
    Name = var.cluster_name
  }
}

resource "aws_subnet" "private_subnet_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block         = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_subnet_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block         = "10.0.2.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "private_subnet_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block         = "10.0.3.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "public_subnet_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block         = "10.0.4.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_subnet" "private_subnet_az3" {
  vpc_id            = aws_vpc.main.id
  cidr_block         = "10.0.5.0/24"
  availability_zone = "us-west-2c"
}

resource "aws_subnet" "public_subnet_az3" {
  vpc_id            = aws_vpc.main.id
  cidr_block         = "10.0.6.0/24"
  availability_zone = "us-west-2c"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `region` set to `us-west-2`.
- **IAM Role**: An IAM role named `eks-cluster-1` is created with an assume role policy allowing the `eks.amazonaws.com` service to assume the role. The `AmazonEKSClusterPolicy` policy is attached to the role.
- **EKS Cluster**: An EKS cluster named `var.cluster_name` is created with the specified IAM role. The cluster uses private and public subnets in the specified AZs. The VPC configuration includes endpoint access settings.
- **Subnets**: Six subnets are created in the VPC, each in a different AZ. The CIDR blocks are chosen to ensure they are within the VPC's CIDR block (`10.0.0.0/16`).
- **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.

### Variables:
- `cluster_name`: A string variable with a default value of `"my-eks-cluster"`.
- `version`: A string variable with a default value of `"1.25.0"`.

This configuration ensures that the EKS cluster is deployed with the specified IAM role and network configuration.

