provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_policy" "s3_event_notifications_policy" {
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sns:Publish"
        Resource = aws_sns_topic.s3_event_notification_topic.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn": "arn:aws:s3:::your-bucket-name/*"
          }
        }
      }
    ]
  })
}

resource "aws_sns_topic" "s3_event_notification_topic" {
  name = "s3-event-notification-topic"
  policy = aws_iam_policy.s3_event_notifications_policy.arn
}

resource "aws_s3_bucket" "your_bucket_name" {
  bucket = "your-bucket-name"
  acl = "private"
  tags = {
    Name = "Your Bucket"
  }

  lifecycle_rule {
    id     = "Delete old logs"
    enabled = true
    prefix = "*.log"
    expiration {
      days = 30
    }
  }

  notification_configuration {
    s3 {
      events = ["s3:ObjectCreated:*"]

      lambda_function {
        events = ["s3:ObjectCreated:*"]
        function_arn = aws_lambda_function.your_lambda_function.arn
        filter_prefix = "*.log"
      }
    }
  }
}

resource "aws_lambda_function" "your_lambda_function" {
  filename      = "path/to/your/lambdafunction.zip"
  function_name = "YourLambdaFunction"
  role          = aws_iam_role.your_lambda_role.arn
  handler       = "index.handler"

  runtime = "python3.8"

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.your_bucket_name.bucket
    }
  }

  timeout = 30

  memory_size = 128
}

resource "aws_iam_role" "your_lambda_role" {
  name = "YourLambdaRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  ]
}
```

This Terraform program creates an IAM policy allowing the 's3.amazonaws.com' service to publish to an SNS topic for S3 event notifications, sets up an SNS topic, an S3 bucket with notifications configured for 's3:ObjectCreated:*' events with a filter for '.log' suffix, and a Lambda function to process these notifications. The Lambda function is triggered by the S3 bucket notifications and processes log files.

