  cidr_block       = ["10.0.1.0/24", "10.0.2.0/24"]
  vpc_id          = aws_vpc.example.id
  availability_zone = ["us-west-2a", "us-west-2b"]
}

resource "aws_security_group" "example" {
  name        = "memcached_sg"
  description = "Allow inbound traffic on port 11211"

  ingress {
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elasticache_cluster" "example" {
  cluster_id         = "memcached-cluster"
  engine            = "memcached"
  engine_version     = "1.6.15"
  num_cache_nodes    = 3
  node_type          = "cache.t3.micro"
  security_groups    = [aws_security_group.example.id]
  subnet_group_name = aws_elasticache_subnet_group.example.name
}

resource "aws_elasticache_subnet_group" "example" {
  name       = "memcached-subnet-group"
  description = "Subnet group for memcached cluster"

  subnet_ids = aws_subnet.example[*].id
}
```

This Terraform program creates a VPC, subnets, security group, and an Elasticache Memcached cluster in the `us-west-2` region. The cluster is configured with three `cache.t3.micro` nodes, and the security group allows inbound traffic on port 11211. The subnet group is associated with the subnets created in the VPC.

