  code {
    s3_bucket = "my-lambda-bucket"
    s3_key   = "example_lambda.zip"
  }
}

resource "aws_iam_role" "example_lambda" {
  name = "example_lambda_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
