provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "iam_for_lambda" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_s3_bucket" "lambda_function_payload_bucket" {
  bucket = "my-lambda-function-bucket-${random_string.random_suffix.result}"

  tags = {
    Name = "My Lambda Function Payload Bucket"
  }
}

resource "aws_s3_object" "lambda_function_payload" {
  bucket = aws_s3_bucket.lambda_function_payload_bucket.bucket
  key    = "lambda.js"

  content = <<EOF
// lambda.js
exports.handler = async (event) => {
  console.log('Hello, World!');
  return {
    statusCode: 200,
    body: JSON.stringify({ message: 'Hello, World!' }),
  };
};
EOF
}

resource "aws_lambda_function" "lambda_function_test" {
  function_name = "my-lambda-function"
  role          = aws_iam_role.iam_for_lambda.arn
  runtime       = "nodejs18.x"
  handler       = "index.handler"
  code         = {
    s3_bucket = aws_s3_bucket.lambda_function_payload_bucket.bucket
    s3_key    = aws_s3_object.lambda_function_payload.key
  }

  timeout = 30

  tags = {
    Name = "My Lambda Function"
  }
}

resource "aws_lambda_permission" "lambda_permission" {
  function_name = aws_lambda_function.lambda_function_test.function_name
  statement_id = "AllowInvoke"
  action       = "lambda:InvokeFunction"
  principal   = "events.amazonaws.com"
  source_arn   = "arn:aws:events:${var.aws_region}:${var.aws_account_id}:rule/my-event-rule"
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured with the `us-east-1` region.
- **IAM Role**: An IAM role named `lambda_execution_role` is created with permissions to assume the Lambda service role.
- **S3 Bucket**: A bucket named `my-lambda-function-bucket-${random_string.random_suffix.result}` is created with a random suffix to ensure uniqueness.
- **S3 Object**: A file named `lambda.js` is uploaded to the S3 bucket containing the Lambda function code.
- **Lambda Function**: A Lambda function named `my-lambda-function` is created using the uploaded code. It is associated with the IAM role and set to use the `nodejs18.x` runtime.
- **Lambda Permission**: A permission is added to allow the Lambda function to be invoked by an EventBridge rule (`my-event-rule`).

