provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id = aws_vpc.main_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "private_subnet" {
  vpc_id = aws_vpc.main_vpc.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_launch_template" "linux_2_template" {
  image_id = "ami-0c55b159cbfafe1f0"  # Latest Amazon Linux 2 AMI
  instance_type = "t3.micro"
  key_name = "my-key-pair"  # Replace with your key pair name
  security_group_names = ["sg-0abcdef1234567890"]  # Replace with your security group ID
  tags = {
    Name = "Linux 2 Template"
  }
}

resource "aws_ec2_fleet" "ec2_fleet" {
  launch_template_configs {
    launch_template_specification {
      launch_template_id = aws_launch_template.linux_2_template.id
    }
    target_capacity_specification {
      default_target_capacity_type = "spot"
      total_target_capacity = 9
      spot_target_capacity = 5
      on_demand_target_capacity = 4
    }
    on_demand_options {
      allocation_strategy = "lowest-price"
    }
    spot_options {
      allocation_strategy = "lowest-price"
    }
  }
  instance_types = ["t3.micro"]
  valid_from = "2023-10-01T00:00:00Z"
  valid_until = "2023-10-31T23:59:59Z"
}
```

This Terraform program creates a VPC with two subnets, a launch template for AWS Linux 2, and an EC2 Fleet with 5 On-Demand and 4 Spot Instances. The VPC is in the `us-west-2` region, and the subnets are in availability zones `us-west-2a` and `us-west-2b`. The launch template uses the latest Amazon Linux 2 AMI and a t3.micro instance type. The EC2 Fleet is configured to use the launch template and has a valid period from October 1, 2023, to October 31, 2023.

