    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "my_iam_role" {
  name = "my_msk_iam_role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_msk_cluster" "my_msk_cluster" {
  cluster_name = "my-msk-cluster"
  kafka_version = "2.8.1"
  number_of_broker_nodes = 3
  client_authentication {
    unauthenticated = true
  }
  broker_node_group_info {
    client_subnets = [aws_subnet.my_subnet_az1.id, aws_subnet.my_subnet_az2.id, aws_subnet.my_subnet_az3.id]
    instance_type = "t3.micro"
    security_groups = [aws_security_group.my_sg.id]
  }
  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.my_kms_key.arn
  }
  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled = true
        log_group = "/aws/msk/my-msk-cluster"
      }
    }
  }
  open_monitoring {
    prometheus_jmx_exporter {
      enabled = true
    }
  }
  tags = {
    Name = "my-msk-cluster"
  }
}
