    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_kms_key" "kms" {
  description = "MSK KMS Key"
}

resource "aws_cloudwatch_log_group" "log_group" {
  name = "/aws/msk/msk-cluster"
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = "msk-bucket-${random_string.random_suffix.result}"
  acl    = "private"

  lifecycle_rule {
    id      = "DeleteOldLogs"
    prefix  = ""
    status = "Enabled"
    expiration {
      days = 30
    }
  }
}

resource "aws_s3_bucket_acl" "s3_bucket_acl" {
  bucket = aws_s3_bucket.s3_bucket.id
  acl    = "private"
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["kafka.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "firehose_role" {
  name   = "msk-firehose-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  inline_policy {
    name = "msk-firehose-policy"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Action = [
            "logs:PutLogEvents",
            "logs:DescribeLogStreams"
          ]
          Resource = "${aws_cloudwatch_log_group.log_group.arn}/*"
        }
      ]
    })
  }
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name = "msk-firehose-stream"

  destination = "s3"

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.s3_bucket.arn
    role_arn   = aws_iam_role.firehose_role.arn

    buffering_interval = 60
    buffering_size    = 512
    compression_format = "GZIP"
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name = "msk-cluster"
  kafka_version = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = [aws_subnet.subnet_az1.id, aws_subnet.subnet_az2.id, aws_subnet.subnet_az3.id]
    instance_type = "t3.micro"
    security_groups = [aws_security_group.sg.id]

    az_distribution = "DEFAULT"
  }

  client_authentication {
    unauthenticated = true
  }

  configuration_info {
    arn = "arn:aws:kafka:us-west-2:123456789012:configuration:my-config:1"
    revision = 1
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.kms.arn
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        log_group = aws_cloudwatch_log_group.log_group.name
      }
      s3 {
        bucket = aws_s3_bucket.s3_bucket.bucket
        acl    = "private"
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
    }
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "random_string" "random_suffix" {
  length = 8
  special = false
}
