  cidr_block       = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "example_subnet_2" {
  vpc_id          = aws_vpc.example_vpc.id
  cidr_block       = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "example_security_group" {
  vpc_id = aws_vpc.example_vpc.id
  description = "Allow inbound traffic on port 9123 for DAX"
  ingress {
    from_port   = 9123
    to_port     = 9123
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "example_iam_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_dax_subnet_group" "example_dax_subnet_group" {
  name        = "example-dax-subnet-group"
  description = "DAX subnet group for example DAX cluster"
  subnet_ids = [
    aws_subnet.example_subnet_1.id,
    aws_subnet.example_subnet_2.id
  ]
}
