  enable_dns_support = true
}

resource "aws_subnet" "cs_class_subnet1" {
  vpc_id = aws_vpc.cs_class_vpc.id
  cidr_block = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "cs_class_subnet2" {
  vpc_id = aws_vpc.cs_class_vpc.id
  cidr_block = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "cs_class_sg1" {
  vpc_id = aws_vpc.cs_class_vpc.id
  description = "Allow inbound HTTP traffic"
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "cs_class_sg2" {
  vpc_id = aws_vpc.cs_class_vpc.id
  description = "Allow inbound SSH traffic"
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

