  image_id = "ami-0c55b159cbfafe1f0" # Example AMI ID for Ubuntu 20.04 LTS
  instance_type = "t3.micro"
  key_name = "my-key-pair" # Replace with your actual key pair name
  security_group_names = ["default"]
  tags = {
    Name = "PostgreSQLLaunchTemplate"
  }
}

resource "aws_ec2_fleet" "database_fleet" {
  launch_template_configs {
    launch_template_specification {
      launch_template_id = aws_launch_template.postgres_launch_template.id
    }
    target_capacity_specification {
      default_target_capacity_type = "spot"
      total_target_capacity = 1
    }
    spot_options {
      allocation_strategy = "lowest-price"
      instance_interruption_behavior = "terminate"
    }
  }
}
