provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "my_vpc" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "my_rds_subnet" {
  count           = 2
  vpc_id          = aws_vpc.my_vpc.id
  cidr_block       = cidrsubnet(aws_vpc.my_vpc.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]
}

resource "aws_security_group" "my_rds_sg" {
  name        = "my-rds-sg"
  description = "Allow inbound traffic on port 3306 from the RDS subnet"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [cidrsubnet(aws_vpc.my_vpc.cidr_block, 16, 0)]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "my_rds_subnet_group" {
  name       = "my-rds-subnet-group"
  subnet_ids = aws_subnet.my_rds_subnet.*.id
}

resource "aws_rds_cluster" "my_rds_cluster" {
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.08.0"
  cluster_identifier = "my-rds-cluster"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  db_subnet_group_name = aws_db_subnet_group.my_rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.my_rds_sg.id]

  backup_retention_period = 7
  skip_final_snapshot    = true
}

resource "aws_iam_role" "my_rds_cluster_role" {
  name = "my-rds-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_db_proxy" "my_db_proxy" {
  name             = "my-rds-proxy"
  engine_family    = "mysql"
  role_arn         = aws_iam_role.my_rds_cluster_role.arn
  vpc_subnet_ids   = aws_subnet.my_rds_subnet.*.id
  require_tls      = true

  auth {
    auth_scheme = "password"
    username    = aws_rds_cluster.my_rds_cluster.master_username
    secret_arn  = aws_secretsmanager_secret.my_rds_cluster_secret.arn
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_secretsmanager_secret" "my_rds_cluster_secret" {
  name = "my-rds-cluster-secret"

  secret_string = jsonencode({
    username = aws_rds_cluster.my_rds_cluster.master_username
    password = aws_rds_cluster.my_rds_cluster.master_password
  })
}
