provider "aws" {
  region = "us-east-1"
}

resource "aws_lightsail_key_pair" "example" {
  name        = "example-key-pair"
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_lightsail_instance" "example" {
  availability_zone = "us-east-1a"
  blueprint_id     = "ubuntu_22_04"
  bundle_id       = "t3.micro"
  name            = "example-instance"

  key_pair_name = aws_lightsail_key_pair.example.name
  user_data     = <<-EOF
    #!/bin/bash
    sudo apt-get update
    sudo apt-get install nginx -y
    EOF
}

resource "aws_lightsail_distribution" "example" {
  bundle_id       = "basic_1gb"
  name            = "example-distribution"

  origin {
    name        = aws_lightsail_instance.example.name
    region_name = aws_lightsail_instance.example.availability_zone
  }

  cache_behavior {
    behavior = "cache"
    path     = "/*"
  }

  cache_behavior_settings {
    allowed_http_methods = ["GET", "HEAD"]
    cached_http_methods = ["GET", "HEAD"]
    default_ttl         = 3600
    maximum_ttl         = 86400
    minimum_ttl         = 60
  }

  default_cache_behavior {
    behavior = "cache"
  }
}
```

This Terraform program creates a basic Amazon Lightsail environment with the following components:
- An AWS provider configured for the `us-east-1` region.
- A Lightsail key pair named `example-key-pair`.
- A Lightsail instance named `example-instance` running Ubuntu 22.04 on a t3.micro bundle.
- A Lightsail distribution named `example-distribution` serving content from the instance. The distribution uses a basic cache behavior for all paths.

