```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lightsail_database" "mysql_database" {
  blueprint_id     = "mysql_5_7"
  bundle_id         = "nano_1gb"
  master_database_name = "mydb"
  master_password   = "SecurePassword123!"
  master_username   = "admin"
  relational_database_name = "mylightsaildb"

  apply_immediately = true
  availability_zone = "us-east-1b"
  backup_retention_enabled = true
  final_snapshot_name = "mylightsaildb-final-snapshot"
  preferred_backup_window = "16:00-16:30"
  preferred_maintenance_window = "17:00-17:30"
  publicly_accessible = false
  skip_final_snapshot = false
  tags = {
    Name = "MyLightsailDB"
  }
}

resource "aws_backup_vault" "mysql_backup_vault" {
  name = "MyLightsailDBBackupVault"
}

resource "aws_backup_plan" "mysql_backup_plan" {
  name = "MyLightsailDBBackupPlan"

  advanced_backup_setting {
    backup_options {
      backup_type = "FULL"
    }
    resource_type = "LAMBDA_FUNCTION"
  }

  rule {
    rule_name = "DailyBackupRule"
    target_vault_name = aws_backup_vault.mysql_backup_vault.name

    schedule_expression = "cron(0 16 * * ? *)"
    schedule_expression_timezone = "UTC"
    start_window = "PT1H"
    completion_window = "PT2H"
  }
}
```

