  internal           = false
  load_balancer_type = "application"

  access_logs {
    bucket = "example-lb-access-logs"
    enabled = true
    prefix = "logs/"
  }

  connection_logs {
    bucket = "example-lb-connection-logs"
    enabled = true
    prefix = "logs/"
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}

resource "aws_lb_listener" "example" {
  load_balancer_arn = aws_lb.example.id
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect_config {
      host = "www.example.com"
      path = "/"
      port = "443"
      protocol = "HTTPS"
    }
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }
}
