provider "aws" {
  region = "us-east-1"
}

resource "aws_efs_file_system" "efs_backup" {
  creation_token = "efs-backup-filesystem"
  encrypted       = true
  tags            = {
    Name = "EFS Backup File System"
  }
}

resource "aws_s3_bucket" "efs_backup_bucket" {
  bucket = "efs-backup-bucket-${var.account_id}"
  acl     = "private"
  tags    = {
    Name = "EFS Backup Bucket"
  }
}

resource "aws_s3_bucket_policy" "efs_backup_bucket_policy" {
  bucket = aws_s3_bucket.efs_backup_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.efs_backup_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_notification" "efs_backup_bucket_notification" {
  bucket = aws_s3_bucket.efs_backup_bucket.bucket

  lambda_function {
    events = ["s3:ObjectCreated:*"]
    lambda_function_arn = aws_lambda_function.efs_backup_lambda.arn
  }
}

resource "aws_lambda_function" "efs_backup_lambda" {
  function_name = "efs-backup-lambda"
  role           = aws_iam_role.efs_backup_lambda_role.arn
  handler        = "index.handler"
  runtime        = "python3.8"
  timeout        = 300
  memory_size     = 128

  code {
    s3_bucket = aws_s3_bucket.efs_backup_bucket.bucket
    s3_key    = "lambda/efs-backup-lambda.zip"
  }

  environment {
    variables = {
      BACKUP_BUCKET_ARN = aws_s3_bucket.efs_backup_bucket.arn
    }
  }

  vpc_config {
    security_group_ids = [aws_security_group.efs_backup_lambda_sg.id]
    subnet_ids         = [aws_subnet.efs_backup_subnet.id]
  }
}

resource "aws_lambda_permission" "efs_backup_lambda_permission" {
  statement_id = "AllowInvokeFunction"
  action       = "lambda:InvokeFunction"
  function_name = aws_lambda_function.efs_backup_lambda.function_name
  principal    = "events.amazonaws.com"
  source_arn   = aws_cloudwatch_event_rule.efs_backup_event_rule.arn
}

resource "aws_cloudwatch_event_rule" "efs_backup_event_rule" {
  name        = "efs-backup-event-rule"
  schedule_expression = "rate(1 hour)"
  description = "Trigger EFS backup every hour"

  targets {
    arn = aws_lambda_function.efs_backup_lambda.arn
  }
}

resource "aws_cloudwatch_event_target" "efs_backup_event_target" {
  arn           = aws_lambda_function.efs_backup_lambda.arn
  rule          = aws_cloudwatch_event_rule.efs_backup_event_rule.name
  target_id      = "EFSBackupLambdaTarget"
  input          = jsonencode({
    FileSystemArn = aws_efs_file_system.efs_backup.arn
  })
}

resource "aws_iam_role" "efs_backup_lambda_role" {
  name = "efs-backup-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "EFSBackupLambdaPolicy"

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "s3:GetObject"
          Resource = "${aws_s3_bucket.efs_backup_bucket.arn}/*"
        },
        {
          Effect   = "Allow"
          Action   = "s3:PutObject"
          Resource = "${aws_s3_bucket.efs_backup_bucket.arn}/*"
        },
        {
          Effect   = "Allow"
          Action   = "s3:DeleteObject"
          Resource = "${aws_s3_bucket.efs_backup_bucket.arn}/*"
        }
      ]
    })
  }
}

resource "aws_security_group" "efs_backup_lambda_sg" {
  name        = "efs-backup-lambda-sg"
  description = "Security group for EFS backup Lambda function"
  vpc_id      = aws_vpc.efs_backup_vpc.id

  ingress {
    from_port   = 0
    to_port     = 65535
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
