    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "efs_backup_subnet" {
  cidr_block          = "10.0.1.0/24"
  availability_zone = "us-east-1a"
  vpc_id             = aws_vpc.efs_backup_vpc.id
}

resource "aws_vpc" "efs_backup_vpc" {
  cidr_block = "10.0.0.0/16"
}
